    # returns int or raises ValueError with appropriate message type
    # Allows optional leading '+'? From tests: '+2' accepted, ' 2' rejected, '2 ' rejected, '002' accepted, '00' zero error, '+0' zero error.
    # Must be decimal digits, optional leading '+'? No leading '-'? '-' rejected as invalid (not zero).
    # Must fit in u32 (1..4294967295, 0 rejected as zero, >max rejected as invalid)
    # Empty rejected as invalid.
    if s is None:
        raise ValueError("invalid")
    if len(s) == 0:
        raise ValueError("invalid")
    # check for leading/trailing spaces? Any space => invalid (since not digit)
    # Python's int(s) would allow spaces? int(' 2') works (strips spaces), but we must reject. So manual check.
    # Allow single leading '+'? What about '++2'? Probably invalid. What about '+ 2'? Invalid.
    orig = s
    if s[0] == '+':
        s = s[1:]
        if len(s) == 0:
            raise ValueError("invalid")
    # Now s must be all digits 0-9, no other chars (no '-', no '.', no 'x', no spaces, etc.)
    if len(s) == 0:
        raise ValueError("invalid")
    for ch in s:
