def is_word(c):
    if c == '\u200c' or c == '\u200d':
        return True
    cat = unicodedata.category(c)
    return cat in ('Lu','Ll','Lt','Lm','Lo','Mn','Mc','Me','Nd','Nl','Pc')

def to_lowercase_no_expand(s):
    # s is whole test case string. If any char would expand (len(c.lower()) != 1), keep whole s as is (no lowercasing). Else lowercase each.
    # c is single-char string, c.lower() is Python lowercasing for that char (may be multi-char for \u0130).
    for ch in s:
        low = ch.lower()
        # ch.lower() for single char: for most, len 1. For \u0130, len 2 ('i' + combining dot). Good.
        if len(low) != 1:
            return s
    # all len 1, lowercase each
    return ''.join(ch.lower() for ch in s)

def escape_codepoint_hex(cp):
    # lowercase hex without leading zeros, e.g., 0xE9 => 'e9', 0x2665 => '2665', 0x1F4A9 => '1f4a9', 0x80 => '80', etc.
    return format(cp, 'x')

def surrogate_pair(cp):
    # cp is astral codepoint 0x10000..0x10FFFF, but excluding 0x10FFFF? Actually for 0x10FFFF, grex does NOT convert (bug). Caller should check: if cp == 0x10FFFF, do not convert (return None or single?). For others in astral, return (high, low) as ints.
    # Formula: cp' = cp - 0x10000, high = cp'//0x400 + 0xD800, low = cp'%0x400 + 0xDC00
    if cp == 0x10FFFF:
        return None
    v = cp - 0x10000
    high = v // 0x400 + 0xD800
    low = v % 0x400 + 0xDC00
    return (high, low)

